665	
666	@layer base {
667	  *,
668	  *::before,
669	  *::after {
670	    border-color: var(--color-border);
671	    outline-color: var(--color-ring);
672	  }
673	
674	  html {
675	    -webkit-font-smoothing: antialiased;
676	    -moz-osx-font-smoothing: grayscale;
677	    text-rendering: optimizeLegibility;
678	  }
679	
680	  body {
681	    background-color: var(--color-background);
682	    color: var(--color-foreground);
683	    font-family: var(--font-sans);
684	  }
685	
686	  h1 {
687	    font-size: var(--text-h1-size);
688	    line-height: var(--text-h1-height);
689	    font-weight: var(--text-h1-weight);
690	    letter-spacing: var(--text-h1-track);
691	  }
692	
693	  h2 {
694	    font-size: var(--text-h2-size);
695	    line-height: var(--text-h2-height);
696	    font-weight: var(--text-h2-weight);
697	    letter-spacing: var(--text-h2-track);
698	  }
699	
700	  h3 {
701	    font-size: var(--text-h3-size);
702	    line-height: var(--text-h3-height);
703	    font-weight: var(--text-h3-weight);
704	    letter-spacing: var(--text-h3-track);
705	  }
706	
707	  /* Global Lucide icon stroke weight — 1.5px matches Linear/Vercel Geist */
708	  svg.lucide {
709	    stroke-width: 1.5;
710	  }
711	
712	  .tabular { font-variant-numeric: tabular-nums; }
713	
714	  /* Global interaction transitions */
715	  button, [role="button"], a, [data-slot="button"] {
716	    transition-property: color, background-color, border-color, box-shadow, transform;
717	    transition-duration: 150ms;
718	    transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
719	  }
720	}
721	
722	@layer utilities {
723	  /* Card hover utility */
724	  .card-interactive {
725	    transition: box-shadow 200ms ease, border-color 200ms ease, transform 200ms ease;
726	  }
727	  .card-interactive:hover {
728	    box-shadow: var(--shadow-soft-md);
729	    border-color: oklch(52% 0.24 292 / 0.2);
730	  }
731	
732	  /* Stagger animation helper */
733	  .stagger-fade-in > * {
734	    opacity: 0;
735	    animation: fade-in-up 0.4s ease forwards;
736	  }
737	  .stagger-fade-in > *:nth-child(1) { animation-delay: 0ms; }
738	  .stagger-fade-in > *:nth-child(2) { animation-delay: 50ms; }
739	  .stagger-fade-in > *:nth-child(3) { animation-delay: 100ms; }
740	  .stagger-fade-in > *:nth-child(4) { animation-delay: 150ms; }
741	  .stagger-fade-in > *:nth-child(5) { animation-delay: 200ms; }
742	  .stagger-fade-in > *:nth-child(6) { animation-delay: 250ms; }
743	
744	  /* Stagger children — 40ms steps */
745	  .stagger-children > * {
746	    opacity: 0;
747	    animation: fade-in-up 0.35s ease-out forwards;
748	  }
749	  .stagger-children > *:nth-child(1)  { animation-delay: 0ms; }
750	  .stagger-children > *:nth-child(2)  { animation-delay: 40ms; }
751	  .stagger-children > *:nth-child(3)  { animation-delay: 80ms; }
752	  .stagger-children > *:nth-child(4)  { animation-delay: 120ms; }
753	  .stagger-children > *:nth-child(5)  { animation-delay: 160ms; }
754	  .stagger-children > *:nth-child(6)  { animation-delay: 200ms; }
755	  .stagger-children > *:nth-child(7)  { animation-delay: 240ms; }
756	  .stagger-children > *:nth-child(8)  { animation-delay: 280ms; }
757	
758	  /* Bulk action bar */
759	  .bulk-action-bar {
760	    position: fixed;
761	    bottom: 24px;
762	    left: 50%;
763	    transform: translateX(-50%);
764	    background: var(--color-surface-elevated, var(--color-card));
765	    border: 1px solid var(--color-border);
766	    border-radius: 0.75rem;
767	    padding: 0.75rem 1rem;
768	    box-shadow: 0 8px 32px oklch(0% 0 0 / 0.5), 0 0 0 1px oklch(22% 0.03 272);
769	    backdrop-filter: blur(12px);
770	  }
771	}
772	
773	@keyframes shimmer {
774	  0%   { background-position: -200% 0; }
775	  100% { background-position: 200% 0; }
776	}
