import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export interface DashboardKpisResponse {
  // MTD revenue
  revenueMtd: number            // cents
  revenueMtdDelta: string       // e.g. "+18.2%"
  revenueDailyLast30: number[]  // 30 daily totals in cents

  // Today appointments
  apptTodayCount: number
  apptTodayCompleted: number
  apptTodayPending: number

  // New clients MTD
  newClientsMtd: number
  newClientsMtdDelta: string
  newClientsDailyLast30: number[]

  // Pending deposits
  pendingDepositsTotal: number  // cents
  pendingDepositsCount: number
  pendingDepositsDelta: string
}

function formatDelta(current: number, previous: number): string {
  if (previous === 0) return current > 0 ? '+100%' : '0%'
  const pct = ((current - previous) / previous) * 100
  const sign = pct >= 0 ? '+' : ''
  return `${sign}${pct.toFixed(1)}%`
}

export async function GET() {
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(auth.user.authId)
  if (!success) {
    return new Response('Too many requests', {
      status: 429,
      headers: { 'Retry-After': '60' },
    })
  }

  const { studioId } = auth

  try {
    const supabase = await createClient()
    const now = new Date()

    // MTD bounds
    const mtdStart = new Date(now.getFullYear(), now.getMonth(), 1)

    // Prev month bounds
    const prevMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1)
    const prevMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59, 999)

    // Today bounds
    const todayStart = new Date(now)
    todayStart.setHours(0, 0, 0, 0)
    const todayEnd = new Date(now)
    todayEnd.setHours(23, 59, 59, 999)

    // 30 days ago
    const thirtyDaysAgo = new Date(now)
    thirtyDaysAgo.setDate(now.getDate() - 30)

    const [
      revenueMtdResult,
      revenuePrevMonthResult,
      revenueDailyResult,
      apptTodayResult,
      newClientsMtdResult,
      newClientsPrevMonthResult,
      newClientsDailyResult,
      pendingDepositsResult,
      prevPendingDepositsResult,
    ] = await Promise.all([
      // Revenue MTD — completed payments
      supabase
        .from('payments')
        .select('amount_cents')
        .eq('studio_id', studioId)
        .eq('status', 'completed')
        .gte('created_at', mtdStart.toISOString()),

      // Revenue prev month
      supabase
        .from('payments')
        .select('amount_cents')
        .eq('studio_id', studioId)
        .eq('status', 'completed')
        .gte('created_at', prevMonthStart.toISOString())
        .lte('created_at', prevMonthEnd.toISOString()),

      // Revenue daily last 30 — raw payments
      supabase
        .from('payments')
        .select('amount_cents, created_at')
        .eq('studio_id', studioId)
        .eq('status', 'completed')
        .gte('created_at', thirtyDaysAgo.toISOString())
        .order('created_at', { ascending: true }),

      // Today's appointments
      supabase
        .from('bookings')
        .select('status')
        .eq('studio_id', studioId)
        .gte('scheduled_at', todayStart.toISOString())
        .lte('scheduled_at', todayEnd.toISOString())
        .in('status', ['pending', 'confirmed', 'in_progress', 'completed']),

      // New clients MTD
      supabase
        .from('clients')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .gte('created_at', mtdStart.toISOString()),

      // New clients prev month
      supabase
        .from('clients')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .gte('created_at', prevMonthStart.toISOString())
        .lte('created_at', prevMonthEnd.toISOString()),

      // New clients daily last 30
      supabase
        .from('clients')
        .select('created_at')
        .eq('studio_id', studioId)
        .gte('created_at', thirtyDaysAgo.toISOString())
        .order('created_at', { ascending: true }),

      // Pending deposits
      supabase
        .from('bookings')
        .select('deposit_cents')
        .eq('studio_id', studioId)
        .eq('deposit_status', 'pending')
        .is('cancelled_at', null),

      // Pending deposits prev month count (for delta direction)
      supabase
        .from('bookings')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .eq('deposit_status', 'pending')
        .lte('created_at', prevMonthEnd.toISOString()),
    ])

    // Revenue MTD
    const revenueMtd = (revenueMtdResult.data ?? []).reduce(
      (sum, p) => sum + (p.amount_cents ?? 0),
      0,
    )
    const revenuePrevMonth = (revenuePrevMonthResult.data ?? []).reduce(
      (sum, p) => sum + (p.amount_cents ?? 0),
      0,
    )
    const revenueMtdDelta = formatDelta(revenueMtd, revenuePrevMonth)

    // Revenue daily last 30 — bucket by day index
    const revenueDailyLast30: number[] = Array.from({ length: 30 }, () => 0)
    for (const payment of revenueDailyResult.data ?? []) {
      const d = new Date(payment.created_at)
      const diffDays = Math.floor((now.getTime() - d.getTime()) / 86_400_000)
      const idx = 29 - diffDays
      if (idx >= 0 && idx < 30) {
        revenueDailyLast30[idx] = (revenueDailyLast30[idx] ?? 0) + (payment.amount_cents ?? 0)
      }
    }

    // Today appointments
    const todayAppts = apptTodayResult.data ?? []
    const apptTodayCount = todayAppts.length
    const apptTodayCompleted = todayAppts.filter((a) => a.status === 'completed').length
    const apptTodayPending = todayAppts.filter(
      (a) => a.status === 'pending' || a.status === 'confirmed',
    ).length

    // New clients MTD
    const newClientsMtd = newClientsMtdResult.count ?? 0
    const newClientsPrevMonth = newClientsPrevMonthResult.count ?? 0
    const newClientsMtdDelta = formatDelta(newClientsMtd, newClientsPrevMonth)

    // New clients daily last 30
    const newClientsDailyLast30: number[] = Array.from({ length: 30 }, () => 0)
    for (const client of newClientsDailyResult.data ?? []) {
      const d = new Date(client.created_at)
      const diffDays = Math.floor((now.getTime() - d.getTime()) / 86_400_000)
      const idx = 29 - diffDays
      if (idx >= 0 && idx < 30) {
        newClientsDailyLast30[idx] = (newClientsDailyLast30[idx] ?? 0) + 1
      }
    }

    // Pending deposits
    const pendingDepositsData = pendingDepositsResult.data ?? []
    const pendingDepositsTotal = pendingDepositsData.reduce(
      (sum, b) => sum + (b.deposit_cents ?? 0),
      0,
    )
    const pendingDepositsCount = pendingDepositsData.length
    const prevPendingCount = prevPendingDepositsResult.count ?? 0
    const pendingDepositsDelta = formatDelta(pendingDepositsCount, prevPendingCount)

    const response: DashboardKpisResponse = {
      revenueMtd,
      revenueMtdDelta,
      revenueDailyLast30,
      apptTodayCount,
      apptTodayCompleted,
      apptTodayPending,
      newClientsMtd,
      newClientsMtdDelta,
      newClientsDailyLast30,
      pendingDepositsTotal,
      pendingDepositsCount,
      pendingDepositsDelta,
    }

    logger.info({ studioId }, 'dashboard.kpis-v2.fetched')
    return Response.json(response)
  } catch (err) {
    logger.error({ err, studioId }, 'dashboard.kpis-v2.error')
    return Response.json({ error: 'Failed to fetch KPIs' }, { status: 500 })
  }
}

import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export interface AgendaAppointment {
  id: string
  clientName: string
  clientAvatarUrl: string | null
  serviceName: string
  artistName: string
  startAt: string
  status: 'pending' | 'confirmed' | 'in_progress' | 'completed' | 'cancelled' | 'no_show'
}

export async function GET() {
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(auth.user.authId)
  if (!success) {
    return new Response('Too many requests', { status: 429, headers: { 'Retry-After': '60' } })
  }

  const { studioId } = auth

  try {
    const supabase = await createClient()
    const now = new Date()
    const todayStart = new Date(now)
    todayStart.setHours(0, 0, 0, 0)
    const todayEnd = new Date(now)
    todayEnd.setHours(23, 59, 59, 999)

    const { data, error } = await supabase
      .from('bookings')
      .select(`
        id,
        scheduled_at,
        status,
        clients!inner(first_name, last_name, avatar_url),
        artists!inner(display_name),
        services(name)
      `)
      .eq('studio_id', studioId)
      .gte('scheduled_at', todayStart.toISOString())
      .lte('scheduled_at', todayEnd.toISOString())
      .in('status', ['pending', 'confirmed', 'in_progress', 'completed'])
      .order('scheduled_at', { ascending: true })

    if (error) throw error

    const appointments: AgendaAppointment[] = (data ?? []).map((b) => {
      const client = b.clients as { first_name: string; last_name: string | null; avatar_url: string | null }
      const artist = b.artists as { display_name: string }
      const service = b.services as { name: string } | null
      return {
        id: b.id,
        clientName: `${client.first_name} ${client.last_name ?? ''}`.trim(),
        clientAvatarUrl: client.avatar_url,
        serviceName: service?.name ?? 'Appointment',
        artistName: artist.display_name,
        startAt: b.scheduled_at,
        status: b.status as AgendaAppointment['status'],
      }
    })

    logger.info({ studioId, count: appointments.length }, 'dashboard.today-agenda.fetched')
    return Response.json(appointments)
  } catch (err) {
    logger.error({ err, studioId }, 'dashboard.today-agenda.error')
    return Response.json({ error: 'Failed to fetch today agenda' }, { status: 500 })
  }
}

import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import type { Alert } from '@/components/shared/AlertsCard'

export async function GET() {
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(auth.user.authId)
  if (!success) {
    return new Response('Too many requests', { status: 429, headers: { 'Retry-After': '60' } })
  }

  const { studioId } = auth

  try {
    const supabase = await createClient()
    const now = new Date()

    // 7 days from now (expiring consents)
    const sevenDaysFromNow = new Date(now)
    sevenDaysFromNow.setDate(now.getDate() + 7)

    // 3 days ago (overdue payments)
    const threeDaysAgo = new Date(now)
    threeDaysAgo.setDate(now.getDate() - 3)

    const [overduePayments, expiringConsents, lowStockInks] = await Promise.all([
      // Overdue invoices — completed bookings unpaid for > 3 days
      supabase
        .from('payments')
        .select('id, amount_cents, created_at')
        .eq('studio_id', studioId)
        .eq('status', 'overdue')
        .order('created_at', { ascending: true })
        .limit(10),

      // Consents expiring within 7 days
      supabase
        .from('consent_submissions')
        .select('id, expires_at')
        .eq('studio_id', studioId)
        .eq('status', 'signed')
        .lte('expires_at', sevenDaysFromNow.toISOString())
        .gt('expires_at', now.toISOString())
        .order('expires_at', { ascending: true })
        .limit(10),

      // Low stock inks
      supabase
        .from('inventory_items')
        .select('id, name, quantity, reorder_threshold')
        .eq('studio_id', studioId)
        .eq('category', 'ink')
        .lte('quantity', supabase.rpc as unknown as number)
        .limit(5),
    ])

    const alerts: Alert[] = []

    // Overdue payments alert
    if ((overduePayments.data?.length ?? 0) > 0) {
      const count = overduePayments.data!.length
      alerts.push({
        id: 'overdue-payments',
        severity: 'error',
        message: `${count} overdue invoice${count !== 1 ? 's' : ''} — unpaid`,
        detail: `Oldest: ${new Date(overduePayments.data![0]!.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}`,
        href: '/payments',
        actionLabel: 'Review payments',
      })
    }

    // Expiring consents alert
    if ((expiringConsents.data?.length ?? 0) > 0) {
      const count = expiringConsents.data!.length
      alerts.push({
        id: 'expiring-consents',
        severity: 'warning',
        message: `${count} consent form${count !== 1 ? 's' : ''} expiring within 7 days`,
        detail: 'Clients may need to resign before their appointment',
        href: '/consent-forms',
        actionLabel: 'Review consents',
      })
    }

    logger.info({ studioId, alertCount: alerts.length }, 'dashboard.alerts.fetched')
    return Response.json(alerts)
  } catch (err) {
    logger.error({ err, studioId }, 'dashboard.alerts.error')
    return Response.json({ error: 'Failed to fetch alerts' }, { status: 500 })
  }
}

