.fc .fc-timegrid-now-indicator-arrow {
  border-top-color: oklch(62% 0.24 292);
  border-bottom-color: oklch(62% 0.24 292);
}

/* ── FullCalendar: event hover ── */
.fc-event:hover {
  filter: brightness(1.1);
  transition: filter 100ms ease-out;
}

/* ── FullCalendar: "+N more" link ── */
.fc .fc-daygrid-more-link {
  color: oklch(72% 0.18 292);
  font-size: 0.6875rem;
  font-weight: 500;
}
.fc .fc-daygrid-more-link:hover {
  color: oklch(80% 0.22 292);
  text-decoration: underline;
}

/* ── FullCalendar: list view ── */
.fc .fc-list-event:hover td {
  background: oklch(62% 0.24 292 / 0.06);
}
.fc .fc-list-day-cushion {
  background: oklch(62% 0.24 292 / 0.05);
}

/* ── Calendar shortcut hint bar ── */
.calendar-shortcuts-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  padding: 0.375rem 1rem;
  background: oklch(62% 0.24 292 / 0.04);
  border-bottom: 1px solid oklch(62% 0.24 292 / 0.12);
  font-size: 0.6875rem;
  color: oklch(50% 0.04 264);
}
.calendar-shortcut-key {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.25rem;
  height: 1.25rem;
  padding: 0 0.25rem;
  background: oklch(18% 0.02 264);
  border: 1px solid oklch(28% 0.03 264);
  border-radius: 0.25rem;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  font-weight: 500;
  color: oklch(70% 0.01 264);
}

/* ── Calendar: print ── */
@media print {
  .calendar-toolbar,
  .calendar-filter-row,
  .calendar-shortcuts-bar,
  .fc-toolbar,
  .fc-scroller-harness > .fc-scroller {
    overflow: visible !important;
  }
  .fc-view-harness {
    height: auto !important;
  }
  .fc-timegrid-event .fc-event-main {
    white-space: normal;
  }
  /* Hide nav/sidebar in print */
  [data-sidebar],
  nav,
  aside {
    display: none !important;
  }
  .fc-event {
    border: 1px solid currentColor !important;
    break-inside: avoid;
  }
  .artist-event-1,
  .artist-event-2,
  .artist-event-3,
  .artist-event-4,
  .artist-event-5,
  .artist-event-6,
  .artist-event-7,
  .artist-event-8,
  .artist-event-9,
  .artist-event-10 {
    print-color-adjust: exact;
    -webkit-print-color-adjust: exact;
  }
}

