input.content:
'use client'

import { Users2, Circle, Layers } from 'lucide-react'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { Checkbox } from '@/components/ui/checkbox'
import { Label } from '@/components/ui/label'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

const STATUSES: { value: BookingStatus; label: string }[] = [
  { value: 'pending', label: 'Pending' },
  { value: 'confirmed', label: 'Confirmed' },
  { value: 'in_progress', label: 'In Progress' },
  { value: 'completed', label: 'Completed' },
  { value: 'cancelled', label: 'Cancelled' },
  { value: 'no_show', label: 'No Show' },
]

const STATUS_DOT_CLASSES: Record<BookingStatus, string> = {
  pending: 'bg-[var(--color-status-pending)]',
  confirmed: 'bg-[var(--color-status-confirmed)]',
  in_progress: 'bg-[var(--color-status-in-progress)]',
  completed: 'bg-[var(--color-status-completed)]',
  cancelled: 'bg-[var(--color-status-cancelled)]',
  no_show: 'bg-[var(--color-status-no-show)]',
}

interface Artist {
  id: string
  display_name: string
  sort_order: number
  colorClass: string
}

interface Service {
  id: string
  name: string
}

interface CalendarFilterRowProps {
  artists: Artist[]
  services: Service[]
  filterArtistIds: string[]
  filterStatuses: string[]
  filterServiceIds: string[]
  onArtistFilterChange: (ids: string[]) => void
  onStatusFilterChange: (statuses: string[]) => void
  onServiceFilterChange: (ids: string[]) => void
}

export function CalendarFilterRow({
  artists,
  services,
  filterArtistIds,
  filterStatuses,
  filterServiceIds,
  onArtistFilterChange,
  onStatusFilterChange,
  onServiceFilterChange,
}: CalendarFilterRowProps) {
  const toggleArtist = (id: string) => {
    onArtistFilterChange(
      filterArtistIds.includes(id)
        ? filterArtistIds.filter((a) => a !== id)
        : [...filterArtistIds, id]
    )
  }

  const toggleStatus = (status: string) => {
    onStatusFilterChange(
      filterStatuses.includes(status)
        ? filterStatuses.filter((s) => s !== status)
        : [...filterStatuses, status]
    )
  }

  const toggleService = (id: string) => {
    onServiceFilterChange(
      filterServiceIds.includes(id)
        ? filterServiceIds.filter((s) => s !== id)
        : [...filterServiceIds, id]
    )
  }

  const artistLabel =
    filterArtistIds.length === 0
      ? 'All Artists'
      : filterArtistIds.length === 1
        ? artists.find((a) => a.id === filterArtistIds[0])?.display_name ?? '1 artist'
        : `${filterArtistIds.length} artists`

  const statusLabel =
    filterStatuses.length === 0 ? 'All Statuses' : `${filterStatuses.length} statuses`

  const serviceLabel =
    filterServiceIds.length === 0
      ? 'All Services'
      : filterServiceIds.length === 1
        ? services.find((s) => s.id === filterServiceIds[0])?.name ?? '1 service'
        : `${filterServiceIds.length} services`

  return (
    <div className="calendar-filter-row flex flex-wrap items-center gap-2 border-b border-border/30 px-4 py-2">
      {/* Artist filter */}
      <Popover>
        <PopoverTrigger
          className={cn(
            'inline-flex items-center gap-1.5 rounded-md px-3 h-8 text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-accent transition-colors',
            filterArtistIds.length > 0 && 'text-foreground bg-primary/10 border border-primary/20'
          )}
        >
          <Users2 className="h-3.5 w-3.5" />
          {artistLabel}
        </PopoverTrigger>
        <PopoverContent className="w-52 p-2" align="start">
          <div className="space-y-1">
            <button
              type="button"
              className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-sm hover:bg-accent"
              onClick={() => onArtistFilterChange([])}
            >
              <span className="text-xs text-muted-foreground">All Artists</span>
            </button>
            {artists.map((artist) => (
              <div
                key={artist.id}
                className="flex items-center gap-2 rounded-md px-2 py-1.5 hover:bg-accent cursor-pointer"
                onClick={() => toggleArtist(artist.id)}
              >
                <Checkbox
                  id={`artist-${artist.id}`}
                  checked={filterArtistIds.includes(artist.id)}
                  onCheckedChange={() => toggleArtist(artist.id)}
                />
                <span className={cn('h-2.5 w-2.5 rounded-full shrink-0', artist.colorClass)} />
                <Label htmlFor={`artist-${artist.id}`} className="text-xs cursor-pointer flex-1">
                  {artist.display_name}
                </Label>
              </div>
            ))}
          </div>
        </PopoverContent>
      </Popover>

      {/* Status filter */}
      <Popover>
        <PopoverTrigger
          className={cn(
            'inline-flex items-center gap-1.5 rounded-md px-3 h-8 text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-accent transition-colors',
            filterStatuses.length > 0 && 'text-foreground bg-primary/10 border border-primary/20'
          )}
        >
          <Circle className="h-3.5 w-3.5" />
          {statusLabel}
        </PopoverTrigger>
        <PopoverContent className="w-48 p-2" align="start">
          <div className="space-y-1">
            {STATUSES.map(({ value, label }) => (
              <div
                key={value}
                className="flex items-center gap-2 rounded-md px-2 py-1.5 hover:bg-accent cursor-pointer"
                onClick={() => toggleStatus(value)}
              >
                <Checkbox
                  id={`status-${value}`}
                  checked={filterStatuses.includes(value)}
                  onCheckedChange={() => toggleStatus(value)}
                />
                <span className={cn('h-2 w-2 rounded-full shrink-0', STATUS_DOT_CLASSES[value])} />
                <Label htmlFor={`status-${value}`} className="text-xs cursor-pointer flex-1">
                  {label}
                </Label>
              </div>
            ))}
          </div>
        </PopoverContent>
      </Popover>

      {/* Service filter — only shown when services available */}
      {services.length > 0 && (
        <Popover>
          <PopoverTrigger
            className={cn(
              'inline-flex items-center gap-1.5 rounded-md px-3 h-8 text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-accent transition-colors',
              filterServiceIds.length > 0 && 'text-foreground bg-primary/10 border border-primary/20'
            )}
          >
            <Layers className="h-3.5 w-3.5" />
            {serviceLabel}
          </PopoverTrigger>
          <PopoverContent className="w-52 p-2" align="start">
            <div className="space-y-1">
              <button
                type="button"
                className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-sm hover:bg-accent"
                onClick={() => onServiceFilterChange([])}
              >
                <span className="text-xs text-muted-foreground">All Services</span>
              </button>
              {services.map((service) => (
                <div
                  key={service.id}
                  className="flex items-center gap-2 rounded-md px-2 py-1.5 hover:bg-accent cursor-pointer"
                  onClick={() => toggleService(service.id)}
                >
                  <Checkbox
                    id={`service-${service.id}`}
                    checked={filterServiceIds.includes(service.id)}
                    onCheckedChange={() => toggleService(service.id)}
                  />
                  <Label htmlFor={`service-${service.id}`} className="text-xs cursor-pointer flex-1">
                    {service.name}
                  </Label>
                </div>
              ))}
            </div>
          </PopoverContent>
        </Popover>
      )}
    </div>
  )
}

'use client'

import { Plus } from 'lucide-react'

interface CalendarFabProps {
  onClick: () => void
}

export function CalendarFab({ onClick }: CalendarFabProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label="New appointment"
      className="md:hidden fixed bottom-[calc(1.5rem+env(safe-area-inset-bottom,0px))] right-6 z-40 flex h-14 w-14 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-[var(--shadow-lift)] transition-transform active:scale-95 hover:brightness-110"
    >
      <Plus className="h-6 w-6" aria-hidden="true" />
    </button>
  )
}
